      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-wsl-workspace\",\n  \"description\": \"WSL workspace support for DeepSeek Harness: add a WSL workspace from the web GUI and run the whole agent session (bash + file tools) inside the WSL distribution, VS Code Remote-WSL style. No toolchain install inside WSL required. Works on DSH Desktop as well as dsh web.\",\n  \"version\": \"0.7.9\",\n  \"type\": \"module\",\n  \"packageManager\": \"npm@11.19.0\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/dsh-wsl-workspace-maintainers/dsh-wsl-workspace.git\"\n  },\n  \"main\": \"lib/index.js\",\n  \"scripts\": {\n    \"clean\": \"node scripts/clean-lib.mjs\",\n    \"build\": \"npm run clean && tsdown && node scripts/verify-lib.mjs\",\n    \"verify\": \"node scripts/verify-lib.mjs\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit\",\n    \"typecheck:gate\": \"node scripts/typecheck-gate.mjs\",\n    \"verify:install\": \"node scripts/verify-install.mjs\",\n    \"verify:artifact\": \"node scripts/verify-artifact-identity.mjs\",\n    \"verify:lib-sync\": \"node scripts/verify-lib-sync.mjs\",\n    \"verify:plane\": \"node scripts/verify-plane-log.mjs\",\n    \"ci:pinned\": \"node ci/install-pinned.mjs\",\n    \"test:unit\": \"node --experimental-strip-types --test tests/variants.test.ts tests/paths.test.ts tests/references.test.ts tests/locales.test.ts tests/readme-compat.test.mjs tests/wsl-output-decode.test.ts tests/default-distro-parity.test.ts tests/deliberate-reds.test.mjs tests/probe-hygiene.test.mjs tests/client-classnames.test.ts tests/support/fake-child-process.test.mjs tests/wsl-env.test.ts tests/wsl-bash-protocol.test.ts tests/wsl-bash-starve.test.ts tests/wsl-bash-tty.test.ts tests/pty-readiness.test.mjs scripts/check-portable-spelling.test.mjs scripts/check-unit-closure.mjs tests/tool-contract.test.mjs tests/script-reachability.test.mjs tests/parity-claims.test.mjs tests/docs-debt.test.mjs tests/wsl-run-code-guard.test.ts\",\n    \"lint:portability\": \"node scripts/check-portable-spelling.mjs\",\n    \"lint:portability:strict\": \"node scripts/check-portable-spelling.mjs --strict\",\n    \"test:win32\": \"node --experimental-strip-types --test tests/wsl-skills.test.ts tests/fs-policy.test.ts tests/relay-node.test.mjs\",\n    \"test:node\": \"node --experimental-strip-types --test tests/shell.test.ts tests/fs-execution-context.test.ts tests/wsl-jobs.test.ts tests/wsl-search.test.ts tests/wsl-bash-parity.test.ts tests/wsl-bash-spill.test.ts tests/wsl-terminal-tool.test.ts tests/client-lifecycle.test.mjs tests/consumer-coverage.test.mjs && node tests/host-materialize.mjs && node tests/host-materialize.mjs --pty && node tests/host-declare.mjs && node tests/host-declare.mjs --pty && node tests/persistent-shell-fallback.mjs && node tests/shell-execute-shape.mjs && node scripts/typecheck-gate.mjs --self-test && node scripts/check-rank-parity.mjs --strict && node scripts/check-host-prompt-parity.mjs\",\n    \"test:seams\": \"node scripts/run-seams.mjs\",\n    \"test:node:fresh\": \"npm run build && npm run test:node\",\n    \"test:wsl\": \"node --experimental-strip-types tests/smoke.ts && node --experimental-strip-types tests/exec-shape.mjs && node tests/shell-extra.mjs && node scripts/make-smoke-built.mjs && node --experimental-strip-types tests/smoke-built.ts && node --experimental-strip-types scripts/compatibility/fs-real.mjs && node --experimental-strip-types scripts/compatibility/skills-real.mjs && node --experimental-strip-types scripts/compatibility/search-real.mjs && node --experimental-strip-types scripts/compatibility/relay-real.mjs && node --experimental-strip-types scripts/compatibility/relay-profile-real.mjs\",\n    \"test:rank\": \"node scripts/check-rank-parity.mjs\",\n    \"test:profile\": \"node tests/host-profile-isolation.mjs\",\n    \"test:compat\": \"bash scripts/verify-dsh-compat.sh\",\n    \"test:docs\": \"node scripts/check-docs-parity.mjs && node scripts/unwrap-prose.mjs --check --tree\",\n    \"test:matrix\": \"node scripts/check-release-matrix.mjs\",\n    \"prepack\": \"npm run build\",\n    \"prepublishOnly\": \"node scripts/verify-install.mjs && node scripts/verify-lib-sync.mjs\",\n    \"test:docs-claims\": \"node --experimental-strip-types scripts/run-docs-claims.mjs\",\n    \"test:host-probe\": \"node tests/support/w51-probe.mjs\",\n    \"test:realm-probe\": \"node --experimental-strip-types tests/support/w54-isolate-probe.mjs\",\n    \"test:confine-probe\": \"node --experimental-strip-types tests/support/w78-confine-probe.mjs\",\n    \"test:rc2-consumers\": \"node --experimental-strip-types tests/support/w92-rc2-consumers.mjs\",\n    \"test:command-census\": \"node tests/support/w51-command-census.mjs\",\n    \"test:world\": \"node --experimental-strip-types --test tests/world-consistency.test.mjs\",\n    \"test:client\": \"node --test tests/client-dom.test.mjs\",\n    \"test:artifacts\": \"node --experimental-strip-types --test tests/artifact-semantics.test.mjs\",\n    \"test:install\": \"node --experimental-strip-types --test tests/install-shapes.test.mjs\",\n    \"test:session\": \"node --experimental-strip-types tests/support/g5-session-probe.mjs\"\n  },\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./shell\": \"./lib/shell.js\",\n    \"./fs\": \"./lib/fs.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\"\n      ]\n    },\n    \"compatibility\": {\n      \"dshReleases\": {\n        \"0.1.0-rc.7\": \"compatible\",\n        \"0.1.0-rc.8\": \"compatible\",\n        \"0.1.1-rc.1\": \"compatible\",\n        \"0.1.1-rc.2\": \"compatible\",\n        \"0.1.2-rc.1\": \"compatible\",\n        \"0.1.3-alpha.2\": \"compatible\",\n        \"0.1.5-rc.1\": \"compatible\",\n        \"0.1.5-rc.2\": \"compatible\",\n        \"0.1.7-rc.1\": \"compatible\",\n        \"0.1.7-rc.2\": \"compatible\",\n        \"0.2.0-rc.2\": \"compatible\",\n        \"0.2.1-rc.2\": \"compatible\"\n      }\n    }\n  },\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"js-yaml\": \"^4.1.0\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^22.15.21\",\n    \"jsdom\": \"^26.1.0\",\n    \"react\": \"^19.2.0\",\n    \"react-dom\": \"^19.2.0\",\n    \"tsdown\": \"^0.13.5\",\n    \"typescript\": \"^5.8.3\"\n  },\n  \"engines\": {\n    \"node\": \">=24\"\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"wsl\",\n    \"workspace\",\n    \"plugin\",\n    \"windows\"\n  ],\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"*\",\n    \"@deepseek-ai/dsh-fs\": \"*\",\n    \"@deepseek-ai/dsh-fs-local\": \"*\",\n    \"@deepseek-ai/dsh-sandbox\": \"*\",\n    \"@deepseek-ai/dsh-shell\": \"*\",\n    \"@deepseek-ai/dsh-subprocess\": \"*\",\n    \"@deepseek-ai/dsh-timeout\": \"*\",\n    \"@deepseek-ai/dsh-tool-fs-search\": \"*\",\n    \"@deepseek-ai/dsh-tools\": \"*\",\n    \"@deepseek-ai/schemastery\": \"*\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-fs\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-fs-local\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-sandbox\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-shell\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-subprocess\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-timeout\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-tool-fs-search\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    }\n  },\n  \"files\": [\n    \"li