    {
      "path": "src/host/variants.ts",
      "content": "/**\n * WSL preset-variant generator. For every healthy source preset the roster\n * supplies, a `wsl-<id>` variant is materialized under the roster's user\n * root: the source composition with its shell/filesystem world replaced by\n * the WSL providers, so any mode (standard, minimal, code, cordis, user\n * presets) can run on top of a WSL execution world. The execution world is\n * therefore orthogonal to the mode instead of a mode itself.\n *\n * The transformation is text-level on the top-level rows of the composition\n * (the shape all shipped presets share), with surgical edits for the known\n * special groups; unknown shapes are kept verbatim where possible.\n * @module dsh-wsl-workspace/host/variants\n */\n\n/** Top-level rows that name the execution world and are replaced by the variant's own. */\nconst WORLD_ROWS = new Set(['tool-bash', 'tool-pwsh', 'tool-fs', 'tool-fs-search', 'str-replace-editor', 'tool-str-replace-editor', 'wsl-world', 'filesystem', 'persistent-shell', 'persistent-bash', 'bash-wsl', 'persistent-pwsh', 'terminal-bash', 'terminal-pwsh', 'custom-bash', 'bootstrap-filesystem'])\n\n/** Execution-world rows that register the model-facing editor tool. */\nconst EDITOR_ROWS = new Set(['str-replace-editor', 'tool-str-replace-editor'])\n\n/** The row ids this generator mounts inside its own world group. */\nconst WSL_WORLD_PROVIDER_IDS = ['shell-wsl', 'fs-wsl']\n\n/**\n * The row id of the world's own image read.\n *\n * A preset copied from a generated variant carries it *inside* the `wsl-world` group, so\n * {@link isWslWorldGroup} retires the copied group wholesale and this generator re-emits exactly\n * one image row; the id is named here because the row it mounts is the answer to issue #54 (see\n * {@link wslWorldGroup}).\n */\nconst IMAGE_ROW_ID = 'read-image-wsl'\n\n/**\n * How long the door's terminal backend may see no output before it returns control\n * without having recognised a prompt — the host's `idleSilenceMs`, default 3000.\n *\n * The number comes from a measurement, not from taste (2026-10-06, real ConPTY, real\n * distribution, `D:\\Temp\\issue51-s0\\v4-report.txt`): a send whose prompt the backend\n * recognises settles in 75–136 ms, while every send whose prompt it does not recognise\n * costs the full default — 3.0–3.6 s, measured across seven sends — which is what a\n * whole keyboard conversation would be made of. The recognition path is what a caller\n * gets whenever the previous prompt's tail arrived intact; this knob only bounds the\n * fallback, so lowering it trades the host default's patience for the agent's. 1200 ms\n * stays ~9x above the measured recognition cost and ~2.5x below the default, and the\n * one case it cuts short — a program that is quiet *and* still working — is exactly\n * what the send's own note reports as unresolved instead of claiming a prompt.\n */\nconst TERMINAL_QUIET_MS = 1_200\n\n/**\n * Whether a top-level row is this generator's own WSL world group.\n *\n * A preset copied from a generated variant (a user renaming `wsl-standard` to\n * their own mode, say) carries the group under whatever id the copy kept, so\n * the mounted provider ids identify it even when the row id changed. Without\n * that check the variant would carry two world groups and the loader refuses\n * the whole preset with `duplicate loader entry id: wsl-world`.\n * @param block - the row's lines.\n * @returns true when the row mounts this generator's WSL providers.\n */\nfunction isWslWorldGroup(block: readonly string[]): boolean {\n  const text = block.join('\\n')\n  return WSL_WORLD_PROVIDER_IDS.some((id) => new RegExp(`^\\\\s+- id: ${id}$`, 'm').test(text))\n}\n\n/**\n * The persistent-shell rows: the host's own PTY registry and its config-driven\n * backend, told to run this plugin's relay (so the shell is a WSL one), plus\n * the persistent tool that consumes them.\n *\n * Two shapes matter here. The registry is an agent-owned service — the shipped\n * `persistent-shell` group keeps it in its own `terminals` realm for that\n * reason — so this is a nested group of the world rather than three flat rows.\n * And the persistent tool registers the tool name **`bash`**, exactly like the\n * one-shot `dsh-tool-bash` row it replaces: both cannot be mounted (the tools\n * registry rejects the duplicate and the whole preset fails to load), which is\n * also why DSH's own Minimal mode describes itself as \"a single-tool agent with\n * a persistent shell\". So a world with the relay paths swaps the shell tool\n * instead of adding one, and a world without them keeps the one-shot row.\n *\n * The session tier mounts the same registry and backend for a different\n * consumer: the keyboard door (`wsl_terminal`), which is the only thing in this\n * world that drives a PTY. It must NOT mount the host's persistent tool — that\n * tool's completion check is what issue #51 is about, and it would collide with\n * the session `bash` row over the `bash` name.\n */\nfunction persistentShellRows(\n  relayPath: string,\n  nodePath: string,\n  bashPath: string,\n  terminalToolPath: string,\n  mode: 'session' | 'pty',\n): string[] {\n  if (mode === 'session') {\n    // The pipe-driven shell: one row, no PTY, no terminal readiness contract. It registers the\n    // same `bash` name, so it still takes the one-shot row's place.\n    return [\n      '    # Persistent shell: this plugin drives one long-lived `bash` over',\n      '    # pipes and ends each command with a record carrying its own nonce,',\n      '    # so completion is an event rather than a match against a terminal the',\n      '    # shell is allowed to repaint (issue #51 point 3: three calls hung',\n      '    # 303.8 s in a real Desktop session before the host wiped the shell).',\n      '    - id: bash-wsl',\n      `      name: '${bashPath.replace(/'/g, \"''\")}'`,\n      '      config:',\n      '        timeoutMs: 120000',\n      '        bootTimeoutMs: 20000',\n      // The door needs the host's PTY stack, but not the host's persistent tool:\n      // the same registry + backend pair as the tier above, consumed by this\n      // plugin's `wsl_terminal` instead of by a tool that ends a command by\n      // matching text on a screen the shell may repaint.\n      '    # The keyboard door: the host terminal registry and its backend, pointed',\n      '    # at this plugin\\'s relay, so an interactive `wsl_terminal` session is a',\n      '    # real `wsl.exe … bash -i` under a real PTY. Mounted beside the pipe',\n      '    # shell, not instead of it: the pipe carries every byte and is the',\n      '    # default; this is only for what a pipe cannot answer (a password, a',\n      '    # fingerprint, a REPL, a TUI).',\n      '    - id: terminal-door',\n      '      name: cordis:group',\n      '      group: true',\n      '      isolate:',\n      '        terminals: true',\n      '      config:',\n      '        - id: pty',\n      \"          name: '@deepseek-ai/dsh-terminal'\",\n      '        - id: terminal-wsl',\n      \"          name: '@deepseek-ai/dsh-terminal-bash'\",\n      '          config:',\n      '            backendType: wsl',\n      '            shellDialect: bash',\n      `            shellPath: '${nodePath.replace(/'/g, \"''\")}'`,\n      '            shellArgs:',\n      `              - '${relayPath.replace(/'/g, \"''\")}'`,\n      `            idleSilenceMs: ${TERMINAL_QUIET_MS}`,\n      '        - id: terminal-door-tool',\n      `          name: '${terminalToolPath.replace(/'/g, \"''\")}'`,\n      '          config:',\n      `            quietMs: ${TERMINAL_QUIET_MS}`,\n    ]\n  }\n  return [\n    '    # Persistent shell: the host PTY registry and its backend, running',\n    '    # this plugin\\'s relay, which hands the PTY to `wsl.exe … bash`',\n    '    # (distribution and user come from the session). It registers the',\n    '    # `bash` tool, so it takes the place of the one-shot row above.',\n    '    - id: persistent-shell',\n    '      name: cordis:group',\n    '      group: true',\n    '      isolate:',\n    '        terminals: true',\n    '      config:',\n    '        - id: pty',\n    \"          name: '@deepseek-ai/dsh-terminal'\",\n    '        - id: terminal-wsl',\n    \"          name: '@deepseek-ai/dsh-terminal-bash'\",\n    '          config:',\n    '            backendType: wsl',\n    '            shellDialect: bash',\n    `            shellPath: '${nodePath.replace(/'/g, \"''\")}'`,\n    '            shellArgs:',\n    `              - '${relayPath.replace(/'/g, \"''\")}'`,\n    '        - id: persistent-bash',\n    \"          name: '@deepseek-ai/dsh-tool-bash-persistent'\",\n    '          config:',\n    '            backendType: wsl',\n    ...SHELL_DESCRIPTION_ROWS,\n  ]\n}\n\n/**\n * The persistent tool's model-facing description, replacing the host default.\n *\n * The host tool's default says only that state persists, and its own Minimal\n * preset goes further in the wrong direction by suggesting `sleep 10 &`. Both\n * facts a WSL session needs are missing, and both were learned the hard way:\n *\n *  - The shell is one process for the whole Agent, so a `cd` in one call decides\n *    where the *next* call starts. A model that read the one-shot tool's contract\n *    (\"each call runs in a fresh shell — pass `workdir` instead of using `cd`\")\n *    will be surprised, and a probe left in `/tmp` makes every later relative path\n *    resolve somewhere it never named.\n *  - The host wraps each command as `eval -- $'…'`. A trailing `&` therefore\n *    backgrounds the *whole* wrapped command: the tool's completion marker is\n *    printed before the work runs, so the call reports no output and exit code 0\n *    while the real output arrives later and can land inside the next call's\n *    output window. `( … ) &` on its own line keeps the `&` on the subshell and\n *    leaves the wrapper's sequencing intact.\n *\n * `description` is a supported key on every declared release (its `Config` schema\n * carries it from 0.1.0-rc.7 on), so the override is version-safe.\n */\nconst SHELL_DESCRIPTION_ROWS = [\n  '            description: |-',\n  '              Run commands in a persistent bash shell inside this WSL distribution. State, including',\n  '              the current directory and exported environment variables, persists across calls: use',\n  '              absolute paths or an explicit `cd` at the start of a command instead of relying on where',\n  '              the previous call left the shell. The shell runs as the workspace\\'s Linux user; Windows',\n  '              files are reachable as /mnt/<drive>, and no toolchain install is required.',\n  '              * This tool takes `command` only. It has no `run_in_background` parameter, and passing',\n  '              one is ignored - use the `bash_background` tool when the mode provides it, or background',\n  '              a subshell as below.',\n  '              * To leave work running without a tracked job, put it in a subshell with the `&` on its',\n  '              own line: `( long-job > log 2>&1 ) &`. Then poll the log file in a later call.',\n  '              * Never end a `&&` chain with `&`. That backgrounds the whole command, so the call',\n  '              returns immediately with no output and exit code 0, and the real output arrives later,',\n  '              possibly inside the next call\\'s output.',\n  '              * Avoid commands that wait for stdin: an interactive foreground child can run until the',\n  '              command timeout, and a timeout resets the shell and discards its state.',\n]\n\n/** The injected WSL world group: providers + the bash/fs consumers, entry-local. */\nfunction wslWorldGroup(\n  shellPath: string,\n  fsPath: string,\n  includeEditor: boolean,\n  persistent?: { relayPath: string; nodePath: string; sandboxPath: string; bashPath: string; terminalTool: string; mode: 'session' | 'pty' },\n  searchPath?: string,\n  jobsPath?: string,\n  sawJobs = false,\n  imagePath?: string,\n): string {\n  return [\n    '# ── WSL execution world (dsh-wsl-workspace variant) ─────────────────────',\n    '# The shell and fs services are provided entry-locally (the isolate',\n    '# realm); host services (tools registry, shell-env, jobs) fall through.',\n    '- id: wsl-world',\n    \"  name: cordis:group\",\n    '  group: true',\n    '  isolate:',\n    '    shell: true', // portability-allow: a YAML fragment for a plugin's own `isolate:` block, not a spawn option\n    '    fs: true',\n    // The Windows confinement runner cannot describe a Linux path, so the\n    // world owns the capability (see the sandbox row below) whenever it mounts\n    // a shell that would otherwise call it.\n    ...(persistent === undefined ? [] : ['    sandbox: true']),\n    '  config:',\n    `    - id: shell-wsl`,\n    `      name: '${shellPath.replace(/'/g, \"''\")}'`,\n    '    - id: fs-wsl',\n    `      name: '${fsPath.replace(/'/g, \"''\")}'`,\n    ...(persistent === undefined\n      ? []\n      : [\n          '    - id: sandbox-wsl',\n          `      name: '${persistent.sandboxPath.replace(/'/g, \"''\")}'`,\n        ]),\n    // The shell tool comes from the persistent-shell group when this world has\n    // one (same `bash` name, so only one of the two may be mounted).\n    ...(persistent === undefined\n      ? ['    - id: tool-bash', \"      name: '@deepseek-ai/dsh-tool-bash'\"]\n      : []),\n    '    - id: tool-fs',\n    \"      name: '@deepseek-ai/dsh-tool-fs'\",\n    // The world's answer for `read_image`, mounted beside the row whose registration of it cannot\n    // reach this realm. See `src/host/wsl-image-tool.ts` for what it takes over and why the\n    // isolation above stays.\n    ...(imagePath === undefined\n      ? []\n      : [\n          `    - id: ${IMAGE_ROW_ID}`,\n          `      name: '${imagePath.replace(/'/g, \"''\")}'`,\n        ]),\n    // `grep`/`glob` run inside the distribution, not through the host suite's\n    // Windows ripgrep: same tool names, same model-facing contract, Linux paths\n    // and Linux symlinks. Older editor builds pass no cwd, so the provider\n    // inherits it from the current tool execution.\n    ...(searchPath === undefined\n      ? []\n      : [\n          '    - id: search-wsl',\n          `      name: '${searchPath.replace(/'/g, \"''\")}'`,\n        ]),\n    // The world's `bash` is the host's *persistent* tool, whose schema declares\n    // only `command`: nothing here can start a tracked background job, so the\n    // host's `job_*` tools would always answer \"no background jobs\" and a\n    // `run_in_background` argument would be silently ignored. This row restores\n    // the producer — but only for a source that also mounts the `job_*` control\n    // tools, because a producer without a reader hands out ids nothing can use\n    // (Minimal mode mounts neither). A world that keeps the one-shot bash row\n    // needs no producer either: that tool carries `run_in_background` itself.\n    ...(jobsPath === undefined || persistent === undefined || !sawJobs\n      ? []\n      : [\n          '    - id: jobs-wsl',\n          `      name: '${jobsPath.replace(/'/g, \"''\")}'`,\n        ]),\n    // The editor resolves through this entry-local WSL fs.\n    // Anchored-family presets require this name during bootstrap.\n    ...(includeEditor\n      ? [\n          '    - id: str-replace-editor',\n          \"      name: '@deepseek-ai/dsh-tool-str-replace-editor'\",\n          '      config:',\n          '        maxOutputChars: 16000',\n        ]\n      : []),\n    ...(persistent === undefined ? [] : persistentShellRows(persistent.relayPath, persistent.nodePath, persistent.bashPath, persistent.terminalTool, persistent.mode)),\n    '',\n  ].join('\\n')\n}\n\n/**\n * The sentence appended to a standard-like persona when the variant runs in WSL.\n *\n * It carries no `{{…}}` group on purpose. A persona is a template, and\n * `dsh-system-prompt` resolves every group against the variables registered for\n * that assembly, throwing `unknown prompt variable` before any model request\n * when one is missing. DSH 0.2.x registers only `provider` and `model` — the\n * working directory moved to the working-directory service, which supplies the\n * path as literal user context — so a `{{cwd}}` here killed every `wsl-*`\n * session at turn 1 step 1 (issue #87). The path is still the model's to learn;\n * it just arrives from the service that owns it, not from a template group this\n * plugin would have to keep in sync with someone else's registry.\n */\nconst PERSONA_APPEND = ' Your working directory is inside a WSL (Windows Subsystem for Linux) distribution: the bash tool and the file read/write/edit tools use Linux paths, and the Windows filesystem is reachable as /mnt/<drive> for file migration.'\n\n/** The upstream local-skill provider row, whose watcher cannot watch a UNC share. */\nconst SKILL_FILESYSTEM_ROW = 'skill-filesystem'\n\n/**\n * Turn the local skill provider's watcher off inside a WSL variant.\n *\n * `@deepseek-ai/dsh-skill-filesystem` reports an INCOMPLETE observation when\n * its watcher fails to start, and `dsh-tool-skill` withholds the whole catalog\n * while a snapshot is incomplete. chokidar cannot watch\n * `\\\\wsl.localhost\\<distro>\\...`, so in a WSL session the model never sees the\n * catalog at all - `skill` still loads one by name, but nothing tells the model\n * which skills exist. With the watcher off the discovery completes (the\n * plugin's own provider rescans the share on demand, and the next session gets\n * a fresh catalog); the price is no live refresh inside one running session,\n * which never worked on this substrate anyway.\n * @param block - the row's lines.\n * @returns the row's lines with `watch: false` merged into its config.\n */\nfunction disableSkillWatch(block: readonly string[]): string[] {\n  const lines = [...block]\n  // An explicit `watch:` from the author wins.\n  if (lines.some(line => /^\\s*watch:/.test(line))) return lines\n  const configIndex = lines.findIndex(line => /^\\s*config:\\s*$/.test(line))\n  if (configIndex >= 0) {\n    const childIndent = `${/^(\\s*)/.exec(lines[configIndex] ?? '')?.[1] ?? '  '}  `\n    lines.splice(configIndex + 1, 0, `${childIndent}watch: false`)\n    return lines\n  }\n  const rowIndent = /^(\\s*)/.exec(lines[0] ?? '')?.[1] ?? ''\n  // Insert before the row block's trailing blank line, not after it.\n  let insertAt = lines.length\n  while (insertAt > 0 && (lines[insertAt - 1] ?? '').trim() === '') insertAt -= 1\n  lines.splice(insertAt, 0, `${rowIndent}  config:`, `${rowIndent}    watch: false`)\n  return lines\n}\n\n/** The top-level rows of one composition, as (startLine, endLineExclusive) spans. */\nfunction topLevelSpans(lines: readonly string[]): { start: number; end: number }[] {\n  const spans: { start: number; end: number }[] = []\n  let start = -1\n  for (let index = 0; index < lines.length; index++) {\n    if (lines[index]?.startsWith('- id: ') === true) {\n      if (start >= 0) spans.push({ start, end: index })\n      start = index\n    }\n  }\n  if (start >= 0) spans.push({ start, end: lines.length })\n  return spans\n}\n\n/** The row id of a top-level span, or undefined when the first line is malformed. */\nfunction spanId(lines: readonly string[], span: { start: number; end: number }): string | undefined {\n  return /^- id: ([A-Za-z0-9_.-]+)/.exec(lines[span.start] ?? '')?.[1]\n}\n\n/** Persona config scalars that carry model-facing text, in append preference order. */\nconst PERSONA_TARGET_FIELDS = ['suffix', 'text', 'prefix'] as const\n\n/** One persona config scalar: where it sits, and whether it is a block header. */\ninterface PersonaTarget {\n  /** Line index of the scalar inside the persona block. */\n  index: number\n  /** Field name: `suffix`, `text` or `prefix`. */\n  field: string\n  /** Indentation of the scalar's own line. */\n  indent: number\n  /** Block header (`>-`, `|-`, …) when the scalar is folded/literal, else ''. */\n  header: string\n  /** Unquoted inline value when the scalar is inline, else ''. */\n  inline: string\n}\n\n/** Strip one layer of YAML quoting so a value can move into a block scalar. */\nexport function unquoteScalar(value: string): string {\n  const single = /^'(.*)'$/s.exec(value)\n  if (single !== null) return (single[1] ?? '').replace(/''/g, \"'\")\n  const double = /^\"(.*)\"$/s.exec(value)\n  return double !== null ? (double[1] ?? '') : value\n}\n\n/**\n * Locate the persona scalar this transform amends.\n *\n * DSH moved the model-facing prompt text across releases: `text` up to\n * v0.1.2-rc.1, and `prefix` + `suffix` from v0.1.3-alpha.2 on. `suffix` wins\n * when both exist because it carries the working-directory sentence, so the\n * appended note lands exactly where the legacy `text` block put it; `prefix`\n * is the last resort for a composition that has neither. A known field with an\n * empty value is not amendable.\n * @param block - the persona row's lines.\n * @returns the target scalar, or undefined when the row carries none.\n */\nfunction personaTarget(block: readonly string[]): PersonaTarget | undefined {\n  for (const field of PERSONA_TARGET_FIELDS) {\n    for (let index = 0; index < block.length; index += 1) {\n      const match = new RegExp(`^(\\\\s*)${field}:\\\\s*(.*)$`).exec(block[index] ?? '')\n      if (match === null) continue\n      const indent = match[1]?.length ?? 0\n      const rest = (match[2] ?? '').trim()\n      if (rest === '' || /^[|>][+-]?$/.test(rest)) {\n        return { index, field, indent, header: rest, inline: '' }\n      }\n      return { index, field, indent, header: '', inline: unquoteScalar(rest) }\n    }\n  }\n  return undefined\n}\n\n/**\n * Index of the last line belonging to the block scalar whose header is at\n * `headerIndex`. A non-blank line at or above the header's indentation is the\n * next sibling key and ends the scalar — without that stop a persona carrying\n * both `suffix` and `prefix` blocks would take the note in the wrong one.\n * @param block - the persona row's lines.\n * @param headerIndex - index of the `field: >-` header line.\n * @param indent - the header's own indentation.\n * @returns the last content line's index, or -1 when the scalar is empty.\n */\nfunction lastBlockLine(block: readonly string[], headerIndex: number, indent: number): number {\n  let last = -1\n  for (let index = headerIndex + 1; index < block.length; index += 1) {\n    const line = block[index] ?? ''\n    if (line.trim() === '') continue\n    const lineIndent = /^(\\s*)/.exec(line)?.[1]?.length ?? 0\n    if (lineIndent <= indent) break\n    last = index\n  }\n  return last\n}\n\n/** Whether a top-level span is a `persona` row this transform may amend. */\nfunction appendablePersona(lines: readonly string[], span: { start: number; end: number }): boolean {\n  const block = lines.slice(span.start, span.end)\n  // `complete: true` asks the persona plugin for no runtime context at all.\n  if (block.join('\\n').includes('complete: true')) return false\n  const target = personaTarget(block)\n  if (target === undefined) return false\n  return target.header === ''\n    ? target.inline !== ''\n    : lastBlockLine(block, target.index, target.indent) >= 0\n}\n\n/**\n * Append the WSL sentence to a persona row's model-facing scalar, in place.\n *\n * A block scalar takes the sentence as a sibling line, which is what the\n * legacy `text: >-` form always did. An inline scalar cannot: it is folded into\n * a block scalar first, so the sentence joins it the same way (and the model\n * sees the same text it saw before v0.1.3-alpha.2).\n * @param lines - the whole composition's lines.\n * @param span - the persona row's span.\n * @returns the persona row's lines, amended when a target was found.\n */\nfunction appendPersona(lines: readonly string[], span: { start: number; end: number }): string[] {\n  const block = [...lines.slice(span.start, span.end)]\n  const target = personaTarget(block)\n  if (target === undefined) return block\n  const pad = ' '.repeat(target.indent)\n  if (target.header !== '') {\n    const last = lastBlockLine(block, target.index, target.indent)\n    if (last < 0) return block\n    const textIndent = /^(\\s*)/.exec(block[last] ?? '')?.[1] ?? `${pad}  `\n    block.splice(last + 1, 0, `${textIndent}${PERSONA_APPEND}`)\n    return block\n  }\n  const child = `${pad}  `\n  block.splice(\n    target.index,\n    1,\n    `${pad}${target.field}: >-`,\n    `${child}${target.inline}`,\n    `${child}${PERSONA_APPEND.trim()}`,\n  )\n  return block\n}\n\n/**\n * Transform one source preset composition into its WSL variant: drop the\n * execution-world rows, keep everything else verbatim, and append the WSL\n * world group. A row id that appears twice in the source is kept once, and a\n * world group the source already carries (a preset copied from a generated\n * variant) is replaced rather than duplicated, so the variant always mounts\n * exactly one world pointing at this installation's providers.\n *\n * The source's own persistent-shell group is not re-added as such: it registers\n * the same `bash` tool name as the WSL world's `dsh-tool-bash`, and the tools\n * registry rejects duplicates within one preset layer — the whole variant fails\n * to mount and the session falls back to another preset. Its PTY *backend*, on\n * the other hand, is exactly what a stateful WSL shell needs, and it is\n * config-driven: given the relay in {@link persistentShellRows} it runs\n * `wsl.exe … bash` under the host's PTY, and its tool registers the separate\n * `persistent-bash` name, so the one-shot `bash` above stays as it is.\n * @param source - the source composition text.\n * @param shellPath - absolute path of the plugin's built WSL shell provider.\n * @param fsPath - absolute path of the plugin's built WSL fs provider.\n * @param persistent - the relay, interpreter and sandbox provider a stateful\n *   shell needs; omit to generate a world without the persistent-shell rows.\n * @param searchPath - absolute path of the plugin's built in-distribution\n *   `grep`/`glob` tools; mounted only for a source that had `tool-fs-search`.\n * @param jobsPath - absolute path of the plugin's built background-job producer\n *   for the persistent shell; mounted only alongside that shell.\n * @param imagePath - absolute path of the plugin's built image read, which answers for\n *   `read_image` inside this realm; mounted only when a build is supplied for it.\n * @returns the variant composition text.\n */\nexport function transformPresetForWsl(\n  source: string,\n  shellPath: string,\n  fsPath: string,\n  persistent?: { relayPath: string; nodePath: string; sandboxPath: string; bashPath: string; terminalTool: string; mode: 'session' | 'pty' },\n  searchPath?: string,\n  jobsPath?: string,\n  imagePath?: string,\n): string {\n  const lines = source.split('\\n')\n  const spans = topLevelSpans(lines)\n  const kept: string[] = []\n  const seen = new Set<string>()\n  let sawEditor = false\n  let sawSearch = false\n  let sawJobs = false\n  let personaAppended = false\n  for (const span of spans) {\n    const id = spanId(lines, span)\n    if (id === undefined) {\n      kept.push(...lines.slice(span.start, span.end))\n      continue\n    }\n    // Two top-level rows with one id are a loader error (\"duplicate loader\n    // entry id: <id>\"), which makes the whole variant unmountable, so the first\n    // occurrence wins and a copied later one is dropped.\n    if (seen.has(id)) continue\n    seen.add(id)\n    const block = lines.slice(span.start, span.end)\n    if (WORLD_ROWS.has(id) || isWslWorldGroup(block)) {\n      if (EDITOR_ROWS.has(id)) sawEditor = true\n      if (id === 'tool-fs-search') sawSearch = true\n      continue\n    }\n    if (id === SKILL_FILESYSTEM_ROW) {\n      kept.push(...disableSkillWatch(block))\n      continue\n    }\n    if (id === 'persona' && !personaAppended && appendablePersona(lines, span)) {\n      kept.push(...appendPersona(lines, span))\n      personaAppended = true\n      continue\n    }\n    kept.push(...block)\n  }\n  // An editor mounted inside a source group (a copied variant, say) also means\n  // the composition expects one, so the injected world keeps its editor row. The\n  // search tools and the background-job producer follow the same rule: a mode\n  // without them (minimal) must not gain them, and a mode with them must not lose\n  // them. `tool-jobs` is what registers `job_list`/`job_output`/`job_kill`.\n  if (source.includes('str-replace-editor')) sawEditor = true\n  if (source.includes('tool-fs-search')) sawSearch = true\n  if (source.includes('tool-jobs')) sawJobs = true\n  const result = [...kept]\n  if (result.length > 0 && result[result.length - 1] !== '') result.push('')\n  result.push(wslWorldGroup(shellPath, fsPath, sawEditor, persistent, sawSearch ? searchPath : undefined, jobsPath, sawJobs, imagePath))\n  return result.join('\\n').replace(/\\n{3,}/g, '\\n\\n').replace(/\\n+$/, '\\n')\n}\n\n/** Whether an id is one of this plugin's own preset directories. */\nexport function isWslVariantId(id: string): boolean {\n  return id === 'wsl' || /^wsl-[a-z0-9-]+$/.test(id)\n}\n\n/** The variant id for one source preset id. */\nexport function variantIdFor(sourceId: string): string {\n  return `wsl-${sourceId.toLowerCase()}`\n}\n"
    },
    {
      "path": "src/host/wsl-sandbox.ts",
      "content": "/**\n * The WSL world's `sandbox` capability.\n *\n * DSH's confinement seam wraps a command so the host's runner enforces the file\n * policy. That runner describes Windows paths: asked to confine a command whose\n * policy carries a `\\\\wsl.localhost\\…` workspace root it fails outright\n * (`GetNamedSecurityInfoW failed (Win32 1)` — the ACL of a 9P path cannot be\n * read), and even where it worked it could not bound a process that executes on\n * the Linux kernel side. That is why this plugin's bash tool has never gone\n * through it, and why the host's persistent-shell group cannot be reused as-is:\n * its backend calls `sandbox.confine()` before spawning.\n *\n * So the world declares its own provider: commands run unconfined by the\n * Windows runner — the distribution is the boundary — while the file tools keep\n * enforcing the policy themselves, at the resolved real path, in\n * `src/fs.ts`. `enforcement: 'partial'` records that split honestly: within this\n * world the policy is enforced for file effects, not by the wrapped command.\n *\n * @module dsh-wsl-workspace/host/wsl-sandbox\n */\n\nimport { SandboxProvider } from '@deepseek-ai/dsh-sandbox'\nimport type { ConfinedArgv } from '@deepseek-ai/dsh-sandbox'\nimport type { Context } from '@deepseek-ai/cordis'\n\n/** The WSL world's no-op confinement: the caller's argv, unchanged. */\nexport class WslSandboxProvider extends SandboxProvider {\n  constructor(ctx: Context) {\n    super(ctx)\n  }\n\n  /**\n   * Hand back the caller's own argv.\n   * @param argv - the command the caller wants to run.\n   * @returns the same argv, with the world's honest enforcement claim.\n   */\n  override confine(argv: readonly string[]): ConfinedArgv {\n    return {\n      argv: [...argv],\n      enforcement: 'partial',\n      denialSignatures: [],\n      runnerFailureRules: [],\n    }\n  }\n}\n\nexport default WslSandboxProvider\n"
    },
    {
      "path": "src/host/wsl-run-code-guard.ts",
      "content": "/**\n * The WSL world's answer for `run_code` when the host's Windows sandbox cannot be started at all.\n *\n * Issue #78, measured on the maintainer machine 2026-10-13 in a real session with a real model:\n *   · `wsl-ptc` + `workspace-write` + a `\\\\wsl.localhost\\…` root — 83 ms,\n *     `code run failed (worker-exit): GetNamedSecurityInfoW failed (Win32 1)`;\n *   · the same program under `read-only` — 826 ms, answers `1`, and the host itself says\n *     `File sandbox enforcement is partial on this host.`;\n *   · the same program under `danger-full-access` — 558 ms, answers `1`;\n *   · and with this plugin entirely absent, a plain host `ptc` session over the same UNC root fails\n *     with the same sentence, so the fault is not the world this plugin mounts.\n *\n * Why the host reaches here: the Windows sandbox grants write by reading the workspace root's security\n * descriptor (`GetNamedSecurityInfoW`) and setting it back. A `\\\\wsl.localhost\\…` root is a 9P share,\n * which carries no Windows security descriptor, so that read answers `ERROR_INVALID_FUNCTION` and the\n * worker dies before the program runs. Only `workspace-write` asks for the grant, which is why the other\n * two modes answer.\n *\n * What this module does NOT do: it does not make the sandbox work. A real confinement for this world\n * would have to be enforced inside the distribution (the shape discussion\n * deepseek-ai/deepseek-harness#8644 reports for `dsh-plugin-wsl-env`: `wsl.exe … --exec bwrap`). Until\n * someone builds that, the honest options were \"let it run under a no-op sandbox\" and \"say plainly that\n * it cannot run, with the ways out\". The first is a door that looks closed and is open; this file takes\n * the second. The guard fires only in the exact shape that was measured to fail, and the sentence names\n * the settings that do work.\n */\n/** The tool the PTC runtime registers; a guard sees every call, so this is the only name it speaks for. */\nconst RUN_CODE_NAME = 'run_code'\n\n/** The one mode whose grant path is the failing one. */\nconst WRITE_MODE = 'workspace-write'\n\n/**\n * A root the Windows ACL runner cannot read a security descriptor from: the per-distribution 9P shares\n * (`\\\\wsl.localhost\\<distro>\\…` and the legacy `\\\\wsl$\\<distro>\\…`). Deliberately narrower than \"any UNC\",\n * because an ordinary SMB share does have a security descriptor and does not fail.\n * @param root - an absolute path as the policy resolved it.\n */\nexport function isWsl9pRoot (root: string): boolean {\n  const lowered = root.toLowerCase()\n  return lowered.startsWith('\\\\\\\\wsl.localhost\\\\') || lowered.startsWith('\\\\\\\\wsl$\\\\')\n}\n\n/**\n * The refusal. Four sentences, in the order a reader needs them: what was asked, why it cannot start,\n * that this is not a problem with their program, and the three settings that do run.\n * @param root - the session's workspace root, quoted back so the reader sees which path was tested.\n */\nexport function refusalForRoot (root: string): string {\n  return 'run_code cannot start in this session: the Windows file sandbox grants write access by reading '\n    + `the workspace root's security descriptor, and the root here is a WSL 9P share (${root}), which has `\n    + 'none — the host reports `GetNamedSecurityInfoW failed (Win32 1)` before any program runs, so this is '\n    + 'not a problem with the code asked for. Three settings do run: switch this session to read-only (the '\n    + 'host reports enforcement as partial), switch it to danger-full-access, or use the world\\'s own tools '\n    + '(`bash`, `wsl_terminal`, `read`, `write`, `edit`, `grep`, `glob`), which run inside the distribution. '\n    + 'A sandbox enforced inside the distribution itself is the open work tracked as issue #78.'\n}\n\n/** What a guard may read about one call, narrowed to the fields this decision uses. */\ninterface ExecFace {\n  name?: string\n  arguments?: Record<string, unknown>\n  agent?: { session?: Record<string, unknown> }\n}\n\n/** The policy service slice this guard reads; `resolve` is the host's own per-call resolution. */\ninterface PolicyFace {\n  resolve (request: { session?: Record<string, unknown> }): { mode?: string; workspaceRoot?: string }\n}\n\n/**\n * The decision, kept away from the registration so a test can drive all six shapes without a host.\n * @param exec - the tool execution the guard was asked about.\n * @param policy - the session's resolved sandbox policy, or undefined when it cannot be read.\n * @returns the refusal sentence, or undefined to let the call proceed.\n */\nexport function denyRunCodeOn9p (exec: ExecFace, policy: { mode?: string; workspaceRoot?: string } | undefined): string | undefined {\n  if (exec.name !== RUN_CODE_NAME || policy === undefined) return undefined\n  // An escalated call carries the mode the user approved; only the plain session setting is ours to read.\n  if (typeof exec.arguments?.sandbox_permissions === 'string') return undefined\n  if (policy.mode !== WRITE_MODE) return undefined\n  const root = policy.workspaceRoot\n  if (typeof root !== 'string' || !isWsl9pRoot(root)) return undefined\n  return refusalForRoot(root)\n}\n\n/**\n * The slice of a cordis context this module touches. Typed structurally rather than by importing\n * `@deepseek-ai/cordis`, because `tests/wsl-run-code-guard.test.ts` lives in the pure-node bucket and\n * `scripts/check-unit-closure.mjs` reddens that whole bucket over one host package it cannot install.\n */\ninterface GuardContext {\n  get (key: string): unknown\n}\n\n/**\n * Register the guard. It goes through `ctx.get`, not an injected proxy property — the host loader hands\n * out `exports.default ?? exports`, so module-level `inject` never reaches the fiber (the same reason\n * recorded for the shell at `src/host/wsl-bash-tool.ts:456-466` and for the image read in\n * `src/host/wsl-image-tool.ts:213-216`).\n * @param ctx - the plugin's own context; the guard is registered where the tool registry lives.\n */\nexport function applyRunCodeGuard (ctx: GuardContext): void {\n  const tools = ctx.get('tools') as unknown as { guard?: (guard: (exec: ExecFace) => string | undefined) => unknown } | undefined\n  if (typeof tools?.guard !== 'function') return\n  const policy = ctx.get('sandboxPolicy') as unknown as PolicyFace | undefined\n  tools.guard((exec: ExecFace) => denyRunCodeOn9p(exec, policy === undefined ? undefined : policy.resolve({\n    ...exec.agent?.session === undefined ? {} : { session: exec.agent.session },\n  })))\n}\n\nexport default applyRunCodeGuard\n"
    },
    {
      "path": "src/host/wsl-bash-session.ts",
      "content": "/**\n * A long-lived WSL `bash`, driven over pipes.\n *\n * This replaces the arrangement that produced issue #51 point 3: the host's persistent bash tool\n * decides \"the command finished\" by matching bytes in a terminal the shell is allowed to repaint,\n * and an interactive Linux shell repaints its prompt line, which leaves spaces after the sentinel\n * and hangs the call until its 300 s deadline (the erase itself was first attributed to `ESC[<n>X`;\n * the captured stream holds only `ESC[K`, `ESC[2J` and literal spaces — see `wsl-bash-protocol`).\n * Here there is no terminal in the loop at all —\n * completion is a NUL-delimited record carrying a per-command nonce, read straight off the child's\n * stdout.\n *\n * What is kept is the part the persistent shell exists for: one process, so `cd`, exported\n * variables, activated virtualenvs and shell functions survive between calls. What is added is a\n * way to survive a command that never returns. Every frame also reports the shell's working\n * directory and exported environment, so when a call is killed on its deadline the session can be\n * rebuilt and the *next* call sees the state the wedged one left behind — the failure mode the host\n * handles by wiping the shell and telling nobody.\n *\n * @module dsh-wsl-workspace/host/wsl-bash-session\n */\n\nimport type { SubprocessHandle } from '@deepseek-ai/dsh-subprocess'\nimport { deadline, timeoutOf } from '@deepseek-ai/dsh-timeout'\nimport { closeSync, mkdtempSync, openSync, writeSync } from 'node:fs'\nimport { tmpdir } from 'node:os'\nimport { join } from 'node:path'\n\nimport { BOOTSTRAP_COMMAND, dropProtocolEcho, encodeFrame, parseState, readCompletion, readStateRecord, restoreChunks, shellPidOf, stripRecords } from './wsl-bash-protocol.ts'\nimport { FIRST_PROBE_MS, LOOKS_BEFORE_SLOWING, MIN_WAIT_MS, PROBE_DONE_SENTINEL, PROBE_EVERY_MS, PROBE_SLOW_MS, confirmsTerminalRead, culpritPids, describeRows, parseProbe, probeScript, starveOf, stopScript, type StarveKind, type StarveSample } from './wsl-bash-starve.ts'\n\n/** How often the reader looks for a frame's records, in milliseconds. */\nconst POLL_MS = 20\n\n/**\n * A command that defines a function or an alias, by text.\n *\n * The function snapshot is lazy (measured: 61 kB of `declare -f` after this machine's rc files), and\n * a lazy count-based trigger misses a *redefinition* — same count, different body. The textual test\n * is the cheap backstop: it only asks for one extra snapshot on the frames that define something.\n */\nconst DEFINITION = /(?:function\\s+[\\w.-]+|[\\w.-]+\\s*\\(\\s*\\)\\s*\\{|\\balias\\s+\\S+=)/\n\n/** Everything the session needs to start a child and keep one alive. */\nexport interface WslBashSessionSpec {\n  /** `wsl.exe` plus the distribution, user and `bash --norc -i`. */\n  argv: readonly string[]\n  /** Windows-side working directory for the child. Never the UNC session path. */\n  cwd: string\n  /** Explicit child environment, `WSLENV` already merged. */\n  env: Record<string, string>\n  /** SIGTERM→SIGKILL grace handed to the subprocess seam. */\n  graceMs: number\n  /** How long the bootstrap may take before the session counts as unusable. */\n  bootTimeoutMs: number\n  /** Per-stream cap; overflow keeps the tail in memory and spills the whole stream to a file. */\n  maxOutputBytes: number\n  /** Marks every process this session starts, so a rebuild can reap exactly its own leftovers. */\n  sessionToken: string\n  /**\n   * `wsl.exe … -e bash -c`, without the script: what {@link WslBashSession.reapDetached} runs when a\n   * rebuild has to stop processes that detached themselves from the shell being replaced.\n   */\n  reaperArgv: readonly string[]\n  /**\n   * The same, with the distribution's root user, for one probe pass taken when a process hides its own\n   * `/proc` entries. Empty when the world cannot offer it, which is the only case where an unconfirmable\n   * wait has to be judged by silence alone.\n   */\n  witnessArgv: readonly string[]\n}\n\n/** The function count a state record reported, or undefined when it reported none. */\nfunction functionCountOf(state: string): number | undefined {\n  const section = parseState(state)['functions-count'] ?? []\n  const line = section.find(candidate => /^\\d+$/.test(candidate.trim()))\n  return line === undefined ? undefined : Number(line.trim())\n}\n\n/**\n * Drop a leading frame echo from bytes on their way into the stderr spill file.\n *\n * The shell's line editor writes the line it just read to stderr, and that echo is the first thing\n * on the frame's stderr — so it is the file's first line. `stripRecords` removes the records but not\n * the echo, and `dropProtocolEcho` — which does remove it — only ever ran on the answer. Measured\n * 2026-10-11: the spill file's first line was `… } | base64 -w0 )\" # __DSH_WSL_BASH_REC`.\n *\n * The predicate is the answer's own (`dropProtocolEcho`), so the file and the body agree on what is\n * protocol; only a first line that filter would have removed is dropped, and a line the command\n * itself wrote is never touched.\n * @param bytes - the window about to be written, already free of records.\n * @param payload - the frame's encoded payload, for the echo predicate.\n * @param stdinPayload - the frame's encoded stdin text, when it carried one.\n * @returns the same bytes without a leading echo line.\n */\nfunction dropLeadingFrameEcho(bytes: Buffer, payload: string | undefined, stdinPayload: string | undefined): Buffer {\n  const newline = bytes.indexOf(0x0a)\n  if (newline < 0) return bytes\n  const first = bytes.subarray(0, newline + 1).toString('utf8')\n  return dropProtocolEcho(first, payload ?? '', stdinPayload) === '' ? bytes.subarray(newline + 1) : bytes\n}\n\n/**\n * Take the frame's stderr-end marker out of one chunk, keeping every other byte.\n *\n * The marker is a single NUL written after the command, and nothing else is written to fd 2 for this\n * frame — the next frame only goes out once this call has settled — so the marker is the **last byte\n * of the chunk that carries it**. That is the whole rule, and it is what makes a NUL anywhere else\n * the command's own data. Measured 2026-10-11: `printf 'a\\0b\\n' >&2` came back `ab`, because the\n * reader used to filter *every* NUL in the chunk while the same bytes on stdout kept theirs.\n *\n * The one shape this cannot tell apart is a command whose stderr happens to end on a chunk boundary\n * with a NUL of its own; that byte is read as the marker, which settles the wait a little early and\n * costs that one byte. The alternative — treating any NUL as the marker — costs every NUL the\n * command wrote, which is the defect.\n * @param chunk - one `data` event from the stderr pipe.\n * @returns the bytes to keep, and whether this chunk carried the marker.\n */\nexport function splitStderrMarker(chunk: Buffer): { kept: Buffer; markerSeen: boolean } {\n  if (chunk.length === 0 || chunk[chunk.length - 1] !== 0) return { kept: chunk, markerSeen: false }\n  return { kept: chunk.subarray(0, chunk.length - 1), markerSeen: true }\n}\n\n/** One command's outcome, in the shape the tool layer renders. */\nexport interface WslBashRun {\n  stdout: string\n  stderr: string\n  exitCode: number\n  /** True when the deadline killed the command. */\n  timedOut: boolean\n  /** True when the caller's own signal ended it. */\n  aborted: boolean\n  /**\n   * True when the shell process itself ended during this call.\n   *\n   * `aborted` is the caller's action and this is the command's: a model that types `… ; exit 3` has\n   * cancelled nothing, and it has not crashed either — the command asked for the shell to end, the way\n   * a person typing `exit` in their own terminal does. The two need different answers because the tool\n   * renders an abort as a cancelled call and keeps every byte the command produced out of the reply\n   * (measured on the installed 0.7.7 build: `echo out; echo err >&2; exit 3` came back as\n   * `Error: tool call aborted`, with the restart note landing on the *next* call instead).\n   */\n  shellExited: boolean\n  /** True when the session had to be rebuilt to recover from this call. */\n  restarted: boolean\n  /** True when stdout was longer than `maxOutputBytes`. */\n  truncated: boolean\n  /** True when stderr overflowed its cap. */\n  stderrTruncated: boolean\n  /** Complete-stream files for the overflowed streams, in the host one-shot tool's shape. */\n  stdoutSpillPath?: string | undefined\n  stderrSpillPath?: string | undefined\n  /** What a rebuild could not restore, each with its reason. */\n  skipped?: string[] | undefined\n  /** Detached processes this session reaped while rebuilding. */\n  reaped?: number | undefined\n  /**\n   * Set when the watchdog stopped this command because it was waiting for input no one can give it:\n   * `terminal` when that was seen directly, `opaque` when the process runs with privileges the\n   * session's user cannot read inside. The tool decides what to do about it and says which it was.\n   */\n  starved?: StarveKind | undefined\n  /** How long the call had been silent when the watchdog stopped it. */\n  starvedAtMs?: number | undefined\n  /** True when the reading that ended the wait came through the root plane rather than the user's own. */\n  starvedViaRoot?: boolean | undefined\n  /** True when the process that had to be stopped was the session shell itself (a builtin reading the\n   * terminal), which is interrupted rather than killed so the session survives. */\n  starvedShellInterrupt?: boolean | undefined\n  /**\n   * True when the watchdog needed to look and every look failed — the `/proc` walk did not answer on\n   * this distribution. Nothing was stopped, and the caller has to be told the check is missing rather\n   * than left to conclude it ran and found nothing.\n   */\n  starveProbeBroken?: boolean | undefined\n  /**\n   * What the last look actually read, when the call reached its deadline after looks that confirmed\n   * nothing. It is the difference between \"the wait was examined and found ordinary\" and \"this\n   * kernel does not expose the wait\" — measured on the WSL1 runner (CI frame 37494104075), where\n   * `/proc/<pid>/wchan` and `/proc/<pid>/syscall` come back empty for every process, asleep or running.\n   */\n  starveSaw?: string | undefined\n}\n\n/** The seam a session needs: enough of the host context to spawn a child. */\nexport interface WslBashSpawnHost {\n  subprocess: {\n    spawn(spec: unknown): SubprocessHandle\n  }\n}\n\n/**\n * What the watchdog remembers while one frame is in flight, so a rule that needs two looks can have\n * the first one without the reader carrying state of its own.\n */\ninterface FrameWatch {\n  /** When the frame went out. */\n  startedAt: number\n  /** The byte count the last look saw; a change means the command is talking, not waiting. */\n  lastBytes: number\n  /** Milliseconds-into-the-call when the last look was taken. */\n  lastLookAt: number\n  /** True when this frame's command runs on a pty the session created (see {@link starveOf}). */\n  ownTerminal: boolean\n  /** The previous look, for the \"CPU is not advancing\" test. */\n  previous?: StarveSample | undefined\n  /** How many looks came back with a completion sentinel, i.e. how many the distribution answered. */\n  looks: number\n  /** How many looks did not answer. All of them, with nothing seen, is the probe being broken here. */\n  failed: number\n  /** Whether the root-plane witness has been consulted for this frame (at most once). */\n  witnessed: boolean\n  /** True when the stop was decided on a reading taken through the root plane. */\n  viaRoot: boolean\n  /** Set once, when the command was stopped. */\n  stop?: { kind: StarveKind, atMs: number, pids: number[] } | undefined\n  /** Set when the frame leaves the reader's hands, so a late probe verdict cannot act on it. */\n  settled?: boolean | undefined\n  /** True while a look is in flight, so one frame never queues probes behind each other. */\n  probing?: boolean | undefined\n}\n\n/**\n * One agent's persistent WSL shell.\n *\n * Commands are serialised: the protocol has one frame in flight, and a second writer would make\n * the first frame's records ambiguous.\n */\nexport class WslBashSession {\n  private readonly ctx: WslBashSpawnHost\n  private readonly spec: WslBashSessionSpec\n  private handle: SubprocessHandle | undefined\n  private exited = false\n  /**\n   * The code the child came back with, once it has come back. Kept because the call that ended the\n   * shell has to report a code, and the only code available to it is the shell's own — which for\n   * `exit 3` is the command's, since bash leaves with the status it was handed.\n   */\n  private exitStatus: number | undefined = undefined\n  private out = Buffer.alloc(0)\n  private outTruncated = false\n  private outSpill: { path: string, fd: number } | undefined\n  /** Absolute byte counts of each stream since the shell started, and how far the file has reached. */\n  private outSeen = 0\n  private outWritten = 0\n  private err = Buffer.alloc(0)\n  /** True once the frame in flight has written its stderr-end marker (a NUL byte) on fd 2. */\n  private errEnded = false\n  /** Set when the blocked process was the shell itself, so the note says the shell was restarted. */\n  private shellInterrupted = false\n  private errTruncated = false\n  private errSpill: { path: string, fd: number } | undefined\n  private errSeen = 0\n  private errWritten = 0\n  /**\n   * Whether this frame's stderr spill file has been written to yet.\n   *\n   * The shell's line editor writes the line it just read to stderr, and that echo is the first\n   * thing on the frame's stderr — so it is the first line of the file unless it is dropped on the\n   * way in. `stripRecords` removes the records but not the echo, and `dropProtocolEcho` (which\n   * does) only ever ran on the answer; measured 2026-10-11, the file's first line was\n   * `… } | base64 -w0 )\" # __DSH_WSL_BASH_REC`.\n   */\n  private errSpillStarted = false\n  /** The frame in flight, for the echo filter the spill file shares with the answer. */\n  private framePayload: string | undefined\n  private frameStdinPayload: string | undefined\n  private journal = ''\n  private functionsBody = ''\n  private functionCount: number | undefined\n  /** Readers parked in {@link waitForOutput}, resolved the moment stdout moves. */\n  private readers: Array<() => void> = []\n  /**\n   * The frame that settled but whose state record has not been consumed yet, if any. The record is the\n   * *first* thing in `out` while this is set — the buffer is consumed up to the completion record, and\n   * the shell writes the state record immediately after it — so it is read from offset 0 and, until it\n   * arrives, `stripRecords` already keeps it out of anything a later window would show.\n   */\n  private pendingState: string | undefined\n  /**\n   * The session shell's own pid inside the distribution, read off the last frame's state record. Zero\n   * until the first frame has settled — which is also the only frame that cannot be watched.\n   */\n  private shellPid = 0\n  /**\n   * Whether the root-plane witness has ever answered for this shell. `undefined` until it is asked,\n   * `false` once an attempt came back empty, so a distribution without a usable root account pays for\n   * that discovery once rather than on every privileged wait.\n   */\n  private witnessAvailable: boolean | undefined\n  private queue: Promise<unknown> = Promise.resolve()\n  private disposed = false\n\n  constructor(ctx: WslBashSpawnHost, spec: WslBashSessionSpec) {\n    this.ctx = ctx\n    this.spec = spec\n  }\n\n  /** Start the child and run the bootstrap. Safe to call once, before any command. */\n  async start(): Promise<void> {\n    await this.spawn()\n    const boot = await this.execute(BOOTSTRAP_COMMAND, this.spec.bootTimeoutMs, undefined, true)\n    if (!boot.settled) {\n      await this.kill()\n      throw new Error('wsl-bash: the persistent shell did not finish its bootstrap within its deadline')\n    }\n    // The state record carries the shell's pid, which the watchdog needs before it can look at anything:\n    // it is written after the frame that reported it, so this is where a startup waits for it — a few\n    // tens of milliseconds once, instead of every call carrying the wait (see `drainState`).\n    await this.settleTail()\n  }\n\n  /**\n   * Run one command, recovering transparently if it wedges the shell.\n   * @param command - the model's command, verbatim.\n   * @param timeoutMs - this call's deadline.\n   * @param signal - the caller's abort signal, if any.\n   * @param ownTerminal - true when this command was wrapped onto a pseudo-terminal that the session\n   *   itself created. The watchdog reads a poll wait on that terminal as unsatisfiable; on an ordinary\n   *   pipe call the same reading would be indistinguishable from a network wait.\n   * @param stdin - the caller's `stdin` text, when the call brought one. It travels inside the frame\n   *   and becomes a file the command's stdin is redirected from (see {@link encodeFrame}); without it\n   *   the command reads `/dev/null`.\n   * @returns the outcome, with `restarted` set when the session had to be rebuilt.\n   */\n  async run(command: string, timeoutMs: number, signal?: AbortSignal, ownTerminal = false, stdin?: string): Promise<WslBashRun> {\n    const previous = this.queue\n    let release: () => void = () => {}\n    this.queue = new Promise<void>(resolve => { release = resolve })\n    await previous\n    try {\n      if (this.disposed) throw new Error('wsl-bash: the session is closed')\n      const first = await this.execute(command, timeoutMs, signal, DEFINITION.test(command), ownTerminal, stdin)\n      if (first.settled) return first.run\n      // A starved frame is not re-executed here: the command was blocked on a terminal, so running it\n      // again in the same kind of shell would block again. The tool retries it on a pseudo-terminal.\n      // The frame went out and no record came back. Two different worlds, and the difference that\n      // matters is whether the command may have run. A dead child cannot still hold the shell, so\n      // replaying there is safe and keeps a crash transparent. A live one may be mid-command, and a\n      // command that merely exceeded its deadline must not be executed a second time — `git commit`,\n      // `curl -X POST`, `rm`. So rebuild either way, which kills whatever is wedged and stops the\n      // *next* call queueing behind it, and re-execute only when the child was already gone.\n      const childGone = this.exited\n      const recovery = await this.rebuild()\n      const recovered = { restarted: true, ...recovery }\n      if (!childGone || signal?.aborted === true || first.run.starved !== undefined) return { ...first.run, ...recovered }\n      const second = await this.execute(command, timeoutMs, signal, DEFINITION.test(command), ownTerminal, stdin)\n      return { ...second.run, ...recovered }\n    } finally {\n      release()\n    }\n  }\n\n  /** Take the shell down and stop recovering. */\n  async dispose(): Promise<void> {\n    this.disposed = true\n    await this.kill()\n    this.closeSpills()\n  }\n\n  /** Spawn the child and attach the readers that feed the protocol. */\n  private async spawn(): Promise<void> {\n    this.out = Buffer.alloc(0)\n    this.err = Buffer.alloc(0)\n    this.outTruncated = false\n    this.errTruncated = false\n    this.outSeen = 0\n    this.outWritten = 0\n    this.errSeen = 0\n    this.errWritten = 0\n    this.exited = false\n    this.exitStatus = undefined\n    // A new child means the previous frame's tail is gone with the old one; anything still parked in\n    // `readers` belongs to that dead reader and must not be resolved by this child's first bytes.\n    this.pendingState = undefined\n    this.readers = []\n    const handle = this.ctx.subprocess.spawn({\n      argv: [...this.spec.argv],\n      cwd: this.spec.cwd,\n      stdio: { stdin: 'pipe', stdout: 'pipe', stderr: 'pipe' },\n      graceMs: this.spec.graceMs,\n      env: this.spec.env,\n    })\n    this.handle = handle\n    handle.stdout?.on('data', (chunk: Buffer) => {\n      this.out = Buffer.concat([this.out, chunk])\n      this.outSeen += chunk.length\n      // The reader is waiting on this, not on a clock: see `waitForOutput`.\n      this.wakeReaders()\n      const cap = this.spec.maxOutputBytes * 2\n      if (this.out.length > cap) {\n        // The record we are waiting for is at the END of the stream, so the head is what goes — and\n        // \"goes\" means into the spill file, because a model that asked for `seq 1 200000` should not\n        // lose the head of it.\n        const cut = this.out.length - cap\n        this.spill('stdout', this.out, cut)\n        this.out = this.out.subarray(cut)\n        this.outTruncated = true\n      }\n    })\n    handle.stderr?.on('data', (chunk: Buffer) => {\n      // The frame's own stderr-end marker: everything the command wrote to fd 2 was written before it.\n      // Only that one byte is protocol; a NUL the command wrote is its data and survives.\n      const { kept, markerSeen } = splitStderrMarker(chunk)\n      if (markerSeen) this.errEnded = true\n      this.err = Buffer.concat([this.err, kept])\n      this.errSeen += kept.length\n      this.wakeReaders()\n      const cap = this.spec.maxOutputBytes * 2\n      if (this.err.length > cap) {\n        // Drop from the start up to the next line boundary: a frame's echo must never reach the\n        // reader as two half-lines, because the half that carries the payload is the only half the\n        // filter can recognise.\n        const from = this.err.length - this.spec.maxOutputBytes\n        const boundary = this.err.indexOf(0x0a, from < 0 ? 0 : from)\n        const cut = boundary < 0 ? this.err.length - cap : boundary + 1\n        this.spill('stderr', this.err, cut)\n        this.err = this.err.subarray(cut)\n        this.errTruncated = true\n      }\n    })\n    void handle.done.then(\n      (outcome) => { this.exited = true; this.exitStatus = outcome?.exitCode ?? undefined },\n      () => { this.exited = true },\n    )\n  }\n\n  /** Append the bytes of the current window that have not reached the stream's spill file yet. */\n  private spillWindow(key: 'stdout' | 'stderr', buffer: Buffer, upto: number): void {\n    const isOut = key === 'stdout'\n    const target = isOut ? this.outSpill : this.errSpill\n    if (target === undefined) return\n    const streamStart = (isOut ? this.outSeen : this.errSeen) - buffer.length\n    const written = isOut ? this.outWritten : this.errWritten\n    const from = Math.max(written, streamStart)\n    const to = streamStart + upto\n    if (to <= from) return\n    let bytes = stripRecords(buffer.subarray(from - streamStart, upto))\n    // The frame's own echo is the first line of the frame's stderr, so it is dropped here with the\n    // same predicate the answer uses — the file is the answer's complete stream, not a place protocol\n    // bytes are allowed to survive.\n    if (!isOut && !this.errSpillStarted) {\n      this.errSpillStarted = true\n      bytes = dropLeadingFrameEcho(bytes, this.framePayload, this.frameStdinPayload)\n    }\n    try {\n      writeSync(target.fd, bytes)\n    } catch {\n      // A spill failure leaves the result with `truncated` and no path, which is what the host's own\n      // reader does (`Spill failures reach the plugin logger; the log line is the only trace`).\n    }\n    if (isOut) this.outWritten = to\n    else this.errWritten = to\n  }\n\n  /** Start the file for a stream that has just overflowed, and write the bytes leaving memory. */\n  private spill(key: 'stdout' | 'stderr', buffer: Buffer, cut: number): void {\n    if ((key === 'stdout' ? this.outSpill : this.errSpill) === undefined) this.openSpill(key)\n    this.spillWindow(key, buffer, cut)\n  }\n\n  /** Create the spill file, named the way the host's one-shot tool names its own. */\n  private openSpill(key: 'stdout' | 'stderr'): { path: string, fd: number } {\n    const directory = mkdtempSync(join(tmpdir(), 'dsh-subprocess-'))\n    const path = join(directory, `dsh-subprocess-${process.pid}-${key === 'stdout' ? 1 : 2}-${this.spec.sessionToken}-${key}.log`)\n    const created = { path, fd: openSync(path, 'wx', 0o600) }\n    if (key === 'stdout') this.outSpill = created\n    else this.errSpill = created\n    return created\n  }\n\n  /** Close the spill files, which is also what makes a rebuilt session stop writing into the old ones. */\n  private closeSpills(): void {\n    for (const record of [this.outSpill, this.errSpill]) {\n      if (record === undefined) continue\n      try { closeSync(record.fd) } catch { /* already gone */ }\n    }\n    this.outSpill = undefined\n    this.errSpill = undefined\n  }\n\n  /**\n   * Write one frame and wait for its records.\n   * @param ownTerminal - whether this command runs on a pseudo-terminal the session created.\n   * @returns the run, plus whether the shell answered at all.\n   */\n  private async execute(command: string, timeoutMs: number, signal: AbortSignal | undefined,\n    forceFunctions = false, ownTerminal = false, stdinText?: string):\n    Promise<{ run: WslBashRun; settled: boolean }> {\n    const handle = this.handle\n    const stdin = handle?.stdin\n    if (handle === undefined || stdin === undefined) {\n      throw new Error('wsl-bash: the session has no stdin to write to')\n    }\n    // Whatever has arrived of the previous frame's state record is collected here — opportunistically,\n    // and never waited for: that wait is for a journal only a *future* rebuild will read, so `rebuild`\n    // is where it belongs (a call that waited here paid ~25 ms for nothing).\n    if (process.env.DSH_WSL_TRACE === '1') console.error(`[trace] start shellPid=${this.shellPid} pending=${String(this.pendingState !== undefined)} out=${this.out.length}`)\n    this.drainState()\n    if (process.env.DSH_WSL_TRACE === '1') console.error(`[trace] drained shellPid=${this.shellPid} pending=${String(this.pendingState !== undefined)} out=${this.out.length}`)\n    // This frame's stderr-end marker has not been seen yet; the settle path waits for it.\n    this.errEnded = false\n    this.shellInterrupted = false\n    // Each frame gets a fresh echo filter for its own spill file.\n    this.errSpillStarted = false\n    // A spill file belongs to one command. Left open across commands, the second call's answer would\n    // carry the first call's `full output` path — measured in `bash-parity-real`, where every probe\n    // after a 200 000-line one reported a spill.\n    this.closeSpills()\n    this.outSeen = this.out.length\n    this.outWritten = 0\n    this.errSeen = this.err.length\n    this.errWritten = 0\n    // `-1` is a function count no shell can report, which is how \"send the bodies whatever the\n    // count\" reaches the frame; `this.functionCount` asks the shell to compare and stay quiet.\n    const frame = encodeFrame(command, forceFunctions ? -1 : this.functionCount, stdinText)\n    const armed = deadline(signal, timeoutMs, 'WSL_BASH_TIMEOUT')\n    // The watchdog's memory for this frame: when it last saw a byte, when it last looked, and what\n    // the look found. Only a frame whose shell pid is known can be watched, because the look walks\n    // that pid's descendants.\n    const watch: FrameWatch = { startedAt: Date.now(), lastBytes: this.out.length + this.err.length, lastLookAt: 0, ownTerminal, looks: 0, failed: 0, witnessed: false, viaRoot: false }\n    this.framePayload = frame.payload\n    this.frameStdinPayload = frame.stdinPayload\n    stdin.write(frame.line)\n    for (;;) {\n      const done = readCompletion(this.out, frame.nonce)\n      if (done !== undefined) {\n        // stderr travels on its own pipe, so the completion record on stdout can arrive first: the wait\n        // has to happen **before** either stream is taken, or it waits for nothing (measured on the src\n        // plane: `echo oops >&2` came back `(no output)` and those bytes landed in the next call's\n        // window).\n        await this.settleStderr()\n        // Both spills are taken **after** that wait, and to the whole window. WSL1 measured the stdout\n        // arm: `seq 1 200000` produced a spill file holding 194341 of the 200000 lines, while WSL2\n        // produced all 200000. The two differ only in how finely the 9P pipe fragments the stream, so\n        // the extra chunks that arrive *during* the stderr wait are the ones missing — they were below\n        // `recordStart` when the spill was taken, and above it by the time the slice was read, so they\n        // reached neither the answer nor the file. 36 kB, about half a pipe chunk.\n        //\n        // The stderr arm had the same defect and kept it longer, because its spill sat *before* the\n        // wait: measured 2026-10-11 on this machine, a `seq 1 200000 >&2` file held 1 011 753 of\n        // 1 288 895 bytes and ended mid-number, while the answer — which `takeStderr` reads after the\n        // wait — had the tail. What was still in flight reached the model and never the file.\n        //\n        // `this.out.length`, not `done.recordStart`: the record is still in the window, and the slice\n        // below strips it, so spilling to the record's offset throws away the bytes after it rather than\n        // the record. What the model is told the file holds has to be what the file holds.\n        this.spillWindow('stderr', this.err, this.err.length)\n        this.spillWindow('stdout', this.out, this.out.length)\n        const stdout = stripRecords(this.out.subarray(0, done.recordStart)).toString('utf8')\n        const stderr = this.takeStderr(frame.payload, frame.stdinPayload)\n        const truncated = this.outTruncated\n        // Captured before the reset below, exactly as `truncated` is: the run has to report the\n        // overflow this call performed, not the state after it was cleared. Hardcoding `false` here is\n        // how a 1.29 MB stderr came back as `truncated: false` with a spill file beside it.\n        const stderrTruncated = this.errTruncated\n        this.out = this.out.subarray(done.nextOffset)\n        this.outTruncated = false\n        this.errTruncated = false\n        // The state record (5 564 bytes and ~25 ms of the shell's own work, measured) is written after\n        // this one and is only needed by a *future* rebuild, so the call settles now and the state is\n        // collected between calls. It sits at the front of the remaining buffer until it arrives, where\n        // `stripRecords` already keeps it out of anything a later window shows.\n        this.pendingState = frame.nonce\n        this.drainState()\n        watch.settled = true\n        armed[Symbol.dispose]()\n        return {\n          settled: true,\n          run: {\n            stdout, stderr, exitCode: done.status, timedOut: false, aborted: false, shellExited: false, restarted: false,\n            truncated, stderrTruncated, ...this.spillPaths(), ...this.starvedFields(watch),\n          },\n        }\n      }\n      const caused = armed.signal.aborted\n      const timedOut = timeoutOf(armed.signal, 'WSL_BASH_TIMEOUT') !== undefined\n      // A deadline that killed the shell is the call's own ending, not the command asking for one.\n      const shellExited = this.exited && !caused && !timedOut\n      if (caused || this.exited) {\n        armed[Symbol.dispose]()\n        this.spillWindow('stderr', this.err, this.err.length)\n        this.spillWindow('stdout', this.out, this.out.length)\n        watch.settled = true\n        return {\n          settled: false,\n          run: {\n            stdout: stripRecords(this.out).toString('utf8'),\n            stderr: this.takeStderr(frame.payload, frame.stdinPayload),\n            exitCode: timedOut ? -1 : (this.exitStatus ?? 1),\n            timedOut,\n            // A frame the watchdog stopped is neither a deadline nor a caller abort: the caller cancelled\n            // nothing, and a builtin that blocked the shell has to reach the tool's retry path (measured:\n            // reporting it as `aborted` made the live gate abort its own run).\n            //\n            // A shell that ended is the same mistake in the other direction: the command asked for it, so\n            // the call has an answer — its own output, and the code the shell left by.\n            aborted: !timedOut && watch.stop === undefined && !shellExited,\n            shellExited,\n            restarted: false,\n            truncated: this.outTruncated,\n            stderrTruncated: this.errTruncated,\n            ...this.spillPaths(),\n            ...this.starvedFields(watch),\n          },\n        }\n      }\n      // The look is not awaited: a probe costs 200–280 ms and would otherwise hold this reader still\n      // while a record is already on the wire (measured: a silent `sleep 3` answered 0.27 s late that\n      // way). It is fired and its verdict applied when it lands.\n      this.watchFrame(watch)\n      await this.waitForOutput(POLL_MS)\n    }\n  }\n\n  /** Resolve every reader waiting on output, so a record is noticed the moment it arrives. */\n  private wakeReaders(): void {\n    const waiting = this.readers\n    this.readers = []\n    for (const resolve of waiting) resolve()\n  }\n\n  /**\n   * Wait for stdout to move, or for the poll interval to pass.\n   *\n   * The reader used to sleep a fixed 20 ms between checks, which put up to that much latency on every\n   * call on top of whatever the shell needed. Waking on arrival removes it; the timer stays as the\n   * safety net for the cases where nothing more will arrive (a timeout, a probe verdict, a death).\n   * @param ms - the longest to wait without any output.\n   */\n  private waitForOutput(ms: number): Promise<void> {\n    return new Promise<void>(resolve => {\n      const done = (): void => { clearTimeout(timer); resolve() }\n      const timer = setTimeout(() => {\n        this.readers = this.readers.filter(reader => reader !== done)\n        resolve()\n      }, ms)\n      this.readers.push(done)\n    })\n  }\n\n  /**\n   * Wait for the frame's stderr-end marker before a settled call reports its answer.\n   *\n   * stdout carries the completion record and stderr carries half the answer, on two pipes with no order\n   * between them, so \"the command is over\" and \"its stderr has arrived\" are not the same instant. The\n   * frame writes one NUL byte on stderr after everything else, so this waits for an event, not for a\n   * guess about how long a pipe takes; without it a cell measured `(no output)` where a command wrote\n   * `oops` to fd 2, with those bytes landing in the *next* call's window.\n   */\n  private async settleStderr(): Promise<void> {\n    const until = Date.now() + 100\n    while (!this.errEnded && Date.now() < until) await this.waitForOutput(2)\n  }\n\n  /**\n   * Consume the state record of the frame that just settled, when it has arrived.\n   *\n   * Called right after settling and again before the next frame goes out, so the journal is up to date\n   * without any call paying for it.\n   */\n  private drainState(): void {\n    const nonce = this.pendingState\n    if (nonce === undefined || this.out.length === 0) return\n    const state = readStateRecord(this.out, nonce, 0)\n    if (state === undefined) return\n    this.journal = this.journalWithFunctions(state.state)\n    this.functionCount = functionCountOf(state.state) ?? this.functionCount\n    this.shellPid = shellPidOf(state.state) ?? this.shellPid\n    this.out = this.out.subarray(state.nextOffset)\n    this.pendingState = undefined\n  }\n\n  /**\n   * Wait for a previous frame's state record before the next one is written.\n   *\n   * Bounded: a state record that never arrives means the shell died between the two, which the next\n   * frame's own timeout reports. The journal simply keeps what it had.\n   */\n  private async settleTail(): Promise<void> {\n    if (this.pendingState === undefined) return\n    const until = Date.now() + 1_000\n    while (this.pendingState !== undefined && Date.now() < until) {\n      await this.waitForOutput(20)\n      this.drainState()\n    }\n  }\n\n  /**\n   * Look once, and stop the command if the look says it is waiting for a keyboard.\n   *\n   * Rate-limited by {@link PROBE_EVERY_MS} and only started after {@link FIRST_PROBE_MS} of silence,\n   * because the look is a second `wsl.exe` and was measured to cost 200–280 ms. A frame that has\n   * written bytes at all is not waited on: the watchdog only ever fires on a call that is silent.\n   *\n   * The look itself is **not awaited**: it is fired here and its verdict is applied by\n   * {@link applyLook} whenever it lands, so the reader keeps consuming output while a probe runs. That\n   * is worth about 0.25 s on a silent command (measured: `sleep 3` used to answer 0.27 s late).\n   * @param watch - this frame's watchdog state.\n   */\n  private watchFrame(watch: FrameWatch): void {\n    if (this.shellPid === 0 || this.spec.reaperArgv.length === 0) return\n    if (watch.stop !== undefined || watch.settled === true || watch.probing === true) return\n    const elapsed = Date.now() - watch.startedAt\n    const bytes = this.out.length + this.err.length\n    if (bytes !== watch.lastBytes) {\n      watch.lastBytes = bytes\n      watch.lastLookAt = elapsed\n      watch.previous = undefined\n      return\n    }\n    if (elapsed < FIRST_PROBE_MS) return\n    // The first looks are the ones that decide; a command that has been silent for many seconds is\n    // sampled slowly rather than shelling out 150 times a minute (see `LOOKS_BEFORE_SLOWING`).\n    const cadence = watch.looks < LOOKS_BEFORE_SLOWING ? PROBE_EVERY_MS : PROBE_SLOW_MS\n    if (elapsed - watch.lastLookAt < cadence) return\n    watch.lastLookAt = elapsed\n    watch.probing = true\n    void this.probeStarve(watch, elapsed)\n      .then(sample => this.applyLook(watch, sample, elapsed))\n      .catch(() => undefined)\n      .finally(() => { watch.probing = false })\n  }\n\n  /**\n   * Apply one look's verdict: classify it, let the root plane settle a privileged wait, and stop the\n   * command when the reading and its window agree.\n   * @param watch - this frame's watchdog state.\n   * @param sample - the rows the pass read, or undefined when the pass did not answer.\n   * @param elapsed - how long the call had been in flight when the look was taken.\n   */\n  private async applyLook(watch: FrameWatch, sample: StarveSample | undefined, elapsed: number): Promise<void> {\n    if (sample === undefined || watch.settled === true || watch.stop !== undefined) return\n    let kind = starveOf(watch.previous, sample, watch.ownTerminal)\n    // The rows that justify the verdict: the user-plane pass, unless it is the witness that settles it —\n    // there the user-plane rows are the unreadable ones (`sudo` shows `wchan=0 tty=-1`), so stopping \"the\n    // pids in the sample\" would stop nothing (measured: the call then ran to its 25 s deadline).\n    let culprits = sample\n    watch.previous = sample\n    if (kind === undefined) return\n    // A privileged wait hides its own `/proc` entries, so the user plane can only call it unconfirmable.\n    // One pass as the distribution's root settles it: either the terminal read is really there — in\n    // which case this is the confirmed reading and acts at once — or the root plane read the wait and it\n    // is something else, in which case nothing is stopped at all. That is what replaced waiting eight\n    // seconds to be sure, and it is why the unconfirmable window can be as short as it is.\n    if (kind === 'opaque' && !watch.witnessed && this.witnessAvailable !== false) {\n      watch.witnessed = true\n      const witness = await this.probeOnce(this.spec.witnessArgv, elapsed)\n      // One failed attempt is enough to stop trying: a distribution without a usable root account would\n      // otherwise pay a failed spawn on every privileged wait, and the reading it falls back to is the\n      // same one that governs when root answers nothing.\n      this.witnessAvailable = witness !== undefined\n      const verdict = confirmsTerminalRead(witness)\n      if (verdict === true) {\n        kind = 'terminal'\n        watch.viaRoot = true\n        if (witness !== undefined) culprits = witness\n      }\n      else if (verdict === false) return\n    }\n    if (elapsed < MIN_WAIT_MS[kind]) return\n    watch.stop = { kind, atMs: elapsed, pids: culpritPids(culprits, kind, watch.ownTerminal) }\n    await this.stopJob(watch.stop.pids)\n  }\n\n  /** The run fields that carry a watchdog stop, or nothing when there was none. */\n  private starvedFields(watch: FrameWatch):\n  Pick<WslBashRun, 'starved' | 'starvedAtMs' | 'starvedViaRoot' | 'starvedShellInterrupt' | 'starveProbeBroken' | 'starveSaw'> {\n    if (watch.stop !== undefined) {\n      return {\n        starved: watch.stop.kind, starvedAtMs: watch.stop.atMs, starvedViaRoot: watch.viaRoot,\n        ...(this.shellInterrupted ? { starvedShellInterrupt: true } : {}),\n      }\n    }\n    // Looked and never got an answer: the check is not running here, which is a fact the caller needs.\n    if (watch.looks === 0 && watch.failed > 0) return { starveProbeBroken: true }\n    // Looked, got answers, and none of them confirmed a wait: say what was seen, because \"timed out\"\n    // alone reads as though the wait had been examined and found ordinary.\n    const saw = describeRows(watch.previous)\n    if (saw !== '') return { starveSaw: saw }\n    // And when there is nothing to show, that is itself the finding: on the WSL1 frame the walk\n    // answered and reported no children at all, which no earlier note distinguished from a look that\n    // never ran. The pid goes in because the walk cannot start without it.\n    if (watch.looks > 0) {\n      return { starveSaw: `the walk answered ${watch.looks} time(s) and reported no child processes (shell pid ${this.shellPid ?? 'unknown'})` }\n    }\n    return { starveSaw: `no look ran before the deadline (shell pid ${this.shellPid ?? 'unknown'})` }\n  }\n\n  /**\n   * One pass of the `/proc` walk, run as the session's own user in a process of its own.\n   * @param watch - this frame's counters, so \"the probe never answered\" can be told to the caller.\n   * @param atMs - how long the call has been in flight.\n   * @returns the rows it read, or undefined when the pass did not answer — a probe that did not answer\n   *   is never read as \"nothing is waiting\", and the run says so.\n   */\n  private async probeStarve(watch: FrameWatch, atMs: number): Promise<StarveSample | undefined> {\n    const sample = await this.probeOnce(this.spec.reaperArgv, atMs)\n    if (sample === undefined) watch.failed += 1\n    else watch.looks += 1\n    return sample\n  }\n\n  /**\n   * One probe pass through whichever plane is asked for.\n   * @param argv - the argv prefix the probe travels on (the session's own user, or root for a witness).\n   * @param atMs - how long the call has been in flight.\n   * @returns the rows it read, or undefined when that plane did not answer.\n   */\n  private async probeOnce(argv: readonly string[], atMs: number): Promise<StarveSample | undefined> {\n    if (argv.length === 0) return undefined\n    const env: Record<string, string> = { ...this.spec.env }\n    delete env.DSH_WSL_SESSION\n    let text = ''\n    try {\n      const handle = this.ctx.subprocess.spawn({\n        argv: [...argv, probeScript(this.shellPid)],\n        cwd: this.spec.cwd,\n        stdio: { stdin: 'ignore', stdout: 'pipe', stderr: 'ignore' },\n        graceMs: this.spec.graceMs,\n        env,\n      })\n      handle.stdout?.on('data', (chunk: Buffer) => { text += chunk.toString('utf8') })\n      await handle.done.catch(() => undefined)\n    } catch {\n      return undefined\n    }\n    return text.includes(PROBE_DONE_SENTINEL) ? parseProbe(text, atMs) : undefined\n  }\n\n  /**\n   * Stop the processes the probe just named, and nothing else.\n   * @param pids - the descendant ids from the last pass.\n   */\n  private async stopJob(pids: readonly number[]): Promise<void> {\n    const env: Record<string, string> = { ...this.spec.env }\n    delete env.DSH_WSL_SESSION\n    // A *builtin* reading the terminal blocks the shell itself, and no signal frees it: SIGINT is caught\n    // and the read syscall is restarted (measured — `kill -INT` left the call running to its deadline),\n    // SIGTSTP stops the shell, and only SIGKILL ends it. So the shell is stopped like any other pid and\n    // the session restarts around the call, which is what `starved` tells the tool to work with.\n    if (pids.includes(this.shellPid)) this.shellInterrupted = true\n    const scripts = [stopScript(pids)]\n    for (const script of scripts) {\n      try {\n        const handle = this.ctx.subprocess.spawn({\n          argv: [...this.spec.reaperArgv, script],\n          cwd: this.spec.cwd,\n          stdio: { stdin: 'ignore', stdout: 'ignore', stderr: 'ignore' },\n          graceMs: this.spec.graceMs,\n          env,\n        })\n        await handle.done.catch(() => undefined)\n      } catch {\n        // Nothing to report: the frame's own deadline still governs.\n      }\n    }\n  }\n\n  /** The complete-stream files, if either stream ever overflowed, in the host's field names. */\n  private spillPaths(): Pick<WslBashRun, 'stdoutSpillPath' | 'stderrSpillPath'> {\n    return {\n      ...(this.outSpill === undefined ? {} : { stdoutSpillPath: this.outSpill.path }),\n      ...(this.errSpill === undefined ? {} : { stderrSpillPath: this.errSpill.path }),\n    }\n  }\n\n  /**\n   * The state record of a settled frame, with the function bodies carried forward.\n   *\n   * The frame only pays for `declare -f` when the function count moved (measured: 61 kB of rc\n   * functions), which means the *next* record has no functions section at all. Replacing the journal\n   * wholesale lost them — measured: after one more command and a rebuild, 91 rc functions came back\n   * and the function defined two calls earlier did not. So the bodies live in their own field and are\n   * re-attached to every journal until a newer snapshot replaces them.\n   */\n  private journalWithFunctions(state: string): string {\n    const sections = parseState(state)\n    if (process.env.DSH_WSL_TRACE === '1') {\n      console.error(`[trace] state record: functions section=${String(sections.functions !== undefined)} `\n        + `bodies=${Buffer.byteLength((sections.functions ?? []).join('\\n'))} markers=${JSON.stringify((sections.functions ?? []).filter(line => line.startsWith('#dsh-functions-')))}`)\n    }\n    if (sections.functions !== undefined) {\n      this.functionsBody = sections.functions.join('\\n')\n      return state\n    }\n    return this.functionsBody === '' ? state : `${state}\\n#dsh-section functions\\n${this.functionsBody}`\n  }\n\n  /**\n   * Hand out the stderr that has completed a line since the last call, keeping any unterminated\n   * tail for the next one.\n   *\n   * The shell echoes each frame line to stderr, and the pipe can deliver that echo in pieces, so a\n   * window cut at a byte offset can start in the middle of an echo — and the half without the\n   * payload in it is unrecognisable as protocol. That is how every real Desktop call came back\n   * with a fragment of its own framing in `[stderr]`. Cutting at line boundaries instead means the\n   * filter always sees a whole echo line, whose tags identify it whatever frame wrote it.\n   *\n   * @param payload - the frame in flight's payload, for the case where the echo is one line.\n   * @param stdinPayload - that frame's stdin payload, which is part of the same echoed line.\n   * @returns the completed, filtered stderr for this call.\n   */\n  private takeStderr(payload: string, stdinPayload?: string): string {\n    const boundary = this.err.lastIndexOf(0x0a)\n    if (boundary < 0) return ''\n    const window = this.err.subarray(0, boundary + 1).toString('utf8')\n    this.err = this.err.subarray(boundary + 1)\n    return dropProtocolEcho(window, payload, stdinPayload)\n  }\n\n  /**\n   * Kill the wedged child and bring back one that knows where we left off.\n   * @returns what the replay could not restore, and how many detached processes were reaped.\n   */\n  private async rebuild(): Promise<{ skipped?: string[] | undefined, reaped?: number | undefined }> {\n    // The last frame's state record may still be on the wire; this is the moment it is worth waiting\n    // for, because the replay below is built out of it. A rebuild already costs a shell boot, so a few\n    // tens of milliseconds here cannot be seen — and no ordinary call pays it any more.\n    await this.settleTail()\n    const restore = restoreChunks(this.journal)\n    if (process.env.DSH_WSL_TRACE === '1') {\n      console.error(`[trace] rebuild: chunks=${restore.chunks.length} `\n        + `functions chunk=${String(restore.chunks.some(chunk => chunk.includes('()')))} skipped=${JSON.stringify(restore.skipped)}`)\n    }\n    await this.kill()\n    this.closeSpills()\n    const reaped = await this.reapDetached()\n    await this.spawn()\n    this.functionCount = undefined\n    // Each chunk is its own frame, and only the last one pays for a function snapshot.\n    for (const [index, chunk] of restore.chunks.entries()) {\n      await this.execute(chunk, this.spec.bootTimeoutMs, undefined, index === restore.chunks.length - 1)\n    }\n    await this.settleTail()\n    return {\n      skipped: restore.skipped.length > 0 ? restore.skipped : undefined,\n      reaped: reaped > 0 ? reaped : undefined,\n    }\n  }\n\n  /**\n   * Stop processes this session started that outlived its shell.\n   *\n   * Measured: killing `wsl.exe` takes its shell's ordinary children with it (0 survivors), but a\n   * command that detached itself (`setsid`, `nohup … &`) survives (2/2). Left alone, every wedged\n   * call would accumulate a process for the rest of the distribution's life. The reaper matches the\n   * `DSH_WSL_SESSION` token this session puts in its children's environment, not a command name —\n   * `pkill -f sleep` would stop a process the user started in another terminal, which is the\n   * mis-kill the positive control in `bash-session-real` exists to catch.\n   * @returns how many processes were stopped.\n   */\n  private async reapDetached(): Promise<number> {\n    if (this.spec.reaperArgv.length === 0) return 0\n    const script = `n=0; for p in /proc/[0-9]*; do if grep -qa 'DSH_WSL_SESSION=${this.spec.sessionToken}' \"$p/environ\" 2>/dev/null; then pid=${'${p#/proc/}'}; kill -9 \"$pid\" 2>/dev/null && n=$((n+1)); fi; done; printf 'REAPED=%s\\\\n' \"$n\"`\n    const env: Record<string, string> = { ...this.spec.env }\n    // The reaper must not carry the token it is looking for, or it would find itself.\n    delete env.DSH_WSL_SESSION\n    let text = ''\n    try {\n      const handle = this.ctx.subprocess.spawn({\n        argv: [...this.spec.reaperArgv, script],\n        cwd: this.spec.cwd,\n        stdio: { stdin: 'ignore', stdout: 'pipe', stderr: 'ignore' },\n        graceMs: this.spec.graceMs,\n        env,\n      })\n      handle.stdout?.on('data', (chunk: Buffer) => { text += chunk.toString('utf8') })\n      await handle.done.catch(() => undefined)\n    } catch {\n      return 0\n    }\n    return Number(/REAPED=(\\d+)/.exec(text)?.[1] ?? '0')\n  }\n\n  /** Terminate the current child, if any, and wait for the seam to report it gone. */\n  private async kill(): Promise<void> {\n    const handle = this.handle\n    this.handle = undefined\n    if (handle === undefined) return\n    handle.terminate()\n    await handle.done.catch(() => undefined)\n  }\n}\n\n/** What a boot-time readiness probe concluded. */\nexport interface WslBashProbeResult {\n  ready: boolean\n  detail: string\n}\n\n/**\n * Start a session, run one computed command through it, and take it down again.\n *\n * This is the question the mount decision actually needs answered: not \"can a child be spawned\"\n * but \"does a command come back\". The host's own PTY probe could pass a world in which every call\n * hung, which is exactly how issue #51 reached a user, so the probe here drives the same protocol\n * the tool will use and requires the computed answer rather than any recognizable text.\n *\n * @param host - the subprocess seam.\n * @param spec - the session spec the world would mount.\n * @param budgetMs - the ceiling for boot plus one command.\n * @returns whether the session is usable, with the reading that decided it.\n */\nexport async function probeWslBashSession(\n  host: WslBashSpawnHost,\n  spec: WslBashSessionSpec,\n  budgetMs = 20_000,\n): Promise<WslBashProbeResult> {\n  const seed = Math.floor(Math.random() * 900) + 100\n  const expected = `dshwslbash${seed * 2}`\n  const session = new WslBashSession(host, spec)\n  const started = Date.now()\n  try {\n    await session.start()\n    const run = await session.run(`echo dshwslbash$(( ${seed} * 2 ))`, Math.max(1_000, budgetMs - (Date.now() - started)))\n    if (run.stdout.includes(expected)) {\n      return { ready: true, detail: `session came up and round-tripped a computed command in ${Date.now() - started}ms` }\n    }\n    return { ready: false, detail: `the session answered but not with the computed value (stdout ${JSON.stringify(run.stdout.slice(0, 80))})` }\n  } catch (error) {\n    return { ready: false, detail: `the session did not come up: ${String(error instanceof Error ? error.message : error).slice(0, 160)}` }\n  } finally {\n    await session.dispose().catch(() => undefined)\n  }\n}\n"
    },
